        { stdio: ['ignore', 'ignore', 'ignore'] },
      );
      SHIPPED_CATALOG = JSON.parse(readFileSync(join(SHIPPED_DIR, 'catalog.json'), 'utf8'));
      // gh-812 rework (review thread 6): ONE batched download of every
      // zip on the previous release replaces ~68 serial per-agent
      // `gh release download` round-trips; shippedZipManifest() below
      // just reads the local copy.
      execSync(
