        { stdio: ['ignore', 'ignore', 'ignore'] },
      );
    } catch (e) {
      const reason = String(e.message).split('\n')[0];
      rmSync(SHIPPED_DIR, { recursive: true, force: true });
      SHIPPED_DIR = null;
      SHIPPED_CATALOG = {};
      if (!ALLOW_UNVERIFIED_BASE) {
