        // catalog removes the version-uniqueness guarantee (the base
        // would fall back to the ledger that caused gh-812) — a degraded
        // release is the exact failure mode this pipeline exists to
        // prevent. A gh outage is transient: the next push retries.
        console.error(`::error::previous release ${PREV_TAG} unavailable (${reason}) and --allow-unverified-base not set — cannot verify shipped versions, failing the release instead of degrading to the versions.json ledger (gh-812)`);
        throw new Error(`shipped catalog of ${PREV_TAG} could not be read (${reason}); pass --allow-unverified-base to release with ledger-based versions (gh-812: never re-ship changed content under a shipped version)`);
      }
      console.warn(`::warning::previous release ${PREV_TAG} unavailable (${reason}) — --allow-unverified-base set: base versions fall back to the versions.json ledger`);
    }
  }
  return SHIPPED_CATALOG;
}
