+                    resolved = true;
+                    break;
+                }
+            }
+            if (!resolved) {
+                unresolved.push({
+                    from: files[i].path,
+                    spec: specs[s],
+                    target: bases[0],
+                    bases: bases,
+                });
+            }
+        }
+    }
+    return unresolved;
+}
