# crap4dart 0.9.5). Install from GitHub — the npm 'crap4js' package is an
# unrelated third-party project.
name: Quality

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:  # the Machine SM / sm-kicker dispatch validation runs

permissions:
  contents: read

env:
  # Ratchet baseline — the measured repo-wide maximum CRAP (see header).
  # Re-measure with the steps below; lower it when the code improves.
  CRAP_THRESHOLD: '4879.8'
  CRAP4JS_REF: 'v0.8.1'

jobs:
  crap:
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 20

      - name: Install pinned tools (separate prefix — never node_modules here)
        run: |
          npm install --prefix "$RUNNER_TEMP/tools" --no-fund --no-audit \
            "github:vabhzw17eg2qu4m9-bit/crap4js#${CRAP4JS_REF}" nyc@17

      - name: Instrument the tree (harness eval-loads bypass nyc's hook)
        run: |
          "$RUNNER_TEMP/tools/node_modules/.bin/nyc" instrument --cwd . . \
            "$RUNNER_TEMP/inst"
          # The harness expects the consumer layout (agents/ checkout beside
          # the cwd) and bare config names — self-symlink covers both.
          ln -sfn "$RUNNER_TEMP/inst" "$RUNNER_TEMP/inst/agents"
          # nyc instrument copies only .js — add the json/md/sh payloads the
          # suite reads (configs, instructions, prompts, fixtures).
          rsync -a --exclude '*.js' --exclude '.git' ./ "$RUNNER_TEMP/inst/"

      - name: Run the unit suite for coverage (instrumented tree)
        # The node harness is a degraded mirror of the dmtools runner
        # (~108 known mock-gap failures, e.g. cli_execute_command stubs);
        # the canonical green-gate is the pack-release test job. Coverage is
        # collected regardless — a red harness must not block the ratchet.
        # ci/run_with_coverage.js wraps the harness and dumps the Istanbul
        # global after the run.
        run: |
          cd "$RUNNER_TEMP/inst"
          FILES="$(node -e "console.log(require('./js/unit-tests/run_all.json').params.jobParams.testFiles.join(' '))")"
          node ci/run_with_coverage.js \
            "$RUNNER_TEMP/inst/js/unit-tests/node_testRunner.js" \
            "$RUNNER_TEMP/cov/coverage-final.json" $FILES \
            || echo "::warning::node harness has known mock gaps — coverage still collected"

      - name: crap4js gate (ratchet — baseline ${{ env.CRAP_THRESHOLD }})
        run: |
          "$RUNNER_TEMP/tools/node_modules/.bin/crap4js" . \
            --coverage "$RUNNER_TEMP/cov/coverage-final.json" \
            --threshold "${CRAP_THRESHOLD}"
                '\n  expected: ' + b +
                '\n  actual:   ' + a
            );
        }
    },
    ok: function(val, msg) {
        if (!val) {
            throw new Error(msg || ('expected truthy, got: ' + JSON.stringify(val)));
        }
    },
    notOk: function(val, msg) {
        if (val) {
            throw new Error(msg || ('expected falsy, got: ' + JSON.stringify(val)));
        }
    },
    contains: function(str, substr, msg) {
        if (typeof str !== 'string' || str.indexOf(substr) === -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' does not contain ' + JSON.stringify(substr)
            );
        }
    },
    notContains: function(str, substr, msg) {
        if (typeof str === 'string' && str.indexOf(substr) !== -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' should not contain ' + JSON.stringify(substr)
            );
        }
    },
    throws: function(fn, msg) {
        var threw = false;
        try { fn(); } catch (e) { threw = true; }
        if (!threw) {
            throw new Error(msg || 'expected function to throw but it did not');
        }
    }
};

function file_read(args) {
    var p = args && args.path ? args.path : args;
    var resolved = path.resolve(process.cwd(), p);
    if (!fs.existsSync(resolved) && p.indexOf('js/') === 0) {
        resolved = path.resolve(process.cwd(), 'agents', p);
    }
    if (!fs.existsSync(resolved) && p.indexOf('agents/') !== 0) {
        resolved = path.resolve(process.cwd(), 'agents', p);
    }
    if (!fs.existsSync(resolved)) {
        throw new Error('file_read: file not found: ' + p);
    }
    return fs.readFileSync(resolved, 'utf8');
}

function loadModule(modulePath, requireFn, mocks) {
    var code = file_read(modulePath);
    if (!code || !code.trim()) {
        throw new Error('loadModule: cannot read file: ' + modulePath);
    }

    var _testMocks_ = mocks || {};
    var preamble = '';
    for (var k in _testMocks_) {
        if (Object.prototype.hasOwnProperty.call(_testMocks_, k)) {
            preamble += 'var ' + k + ' = _testMocks_["' + k + '"];\n';
        }
    }

    var _testModule_ = { exports: {} };
    var _testRequire_ = requireFn || function(id) {
        throw new Error('loadModule: require("' + id + '") not provided for ' + modulePath);
    };

    eval(
        '(function(module, exports, require) {\n' +
        preamble +
        code +
        '\n})(_testModule_, _testModule_.exports, _testRequire_)'
    );

    return _testModule_.exports;
}

function makeRequire(moduleMap) {
    return function(id) {
        if (moduleMap[id]) return moduleMap[id];

        var base = id;
        var slash = id.lastIndexOf('/');
        if (slash !== -1) base = id.substring(slash + 1);
        var noExt = base.replace(/\.js$/, '');

        if (moduleMap[base]) return moduleMap[base];
        if (moduleMap[noExt]) return moduleMap[noExt];
        if (moduleMap['./' + base]) return moduleMap['./' + base];

        throw new Error('makeRequire: module not found: ' + id);
    };
}

