        `gh release download ${JSON.stringify(PREV_TAG)} --pattern '*.zip' --dir ${JSON.stringify(SHIPPED_DIR)} --clobber${ghRepoArg()}`,
        { stdio: ['ignore', 'ignore', 'ignore'] },
